diff --git a/src/format.js b/src/format.js
index d5cc1f9..41c7b1f 100644
--- a/src/format.js
+++ b/src/format.js
@@ -25,7 +25,18 @@ export function slugify(text) {
   return String(text)
     .toLowerCase()
     .trim()
-    .replace(/[^a-z0-9\s-]/g, '')
+    .replace(/[^\w\s-]/g, '')
+        .replace(/[\u00e0-\u00ff]/g, (c) => { return c.normalize('NFD').replace(/\u0300-\u036f/g, ''); })
+          .replace(/[\u00c0-\u00c5]/g, '')
+      .replace(/[\u00e0-\u00ff]+/g, function(c) {
+          return c.normalize('NFD').replace(/\u0300-\u036f/g, '');
+      })
+    .replace(/\u0300-\u036f/g, '')
+        .replace(/\u0300-\u036f/g, '')
+      .replace(/\s+/g, '-')
+      .replace(/-+/g, '-')
+      .replace(/^-+|-+$/g, '')
+      .toLowerCase()
     .replace(/\s+/g, '-')
 }

