+import { formatCurrency, slugify, formatDate, padRight } from '../src/format.js';
+
+// New tests for slugify function
+
+test('slugify handles repeated dashes', () => {
+  assert.equal(slugify('  C++ -- The   Good Parts!  '), 'c-the-good-parts');
+});
+
+test('slugify removes leading and trailing dashes', () => {
+  assert.equal(slugify('-Hello-'), 'hello');
+});
+
+test('slugify transliterates accented letters', () => {
+  assert.equal(slugify('Café Society'), 'cafe-society');
+});

